/*
 * act4_config.h - force-included into every translation unit of a test that
 * links the c_common runtime (see the `-include` flag added by
 * framework/src/act/build_plan.py).
 *
 * It reproduces the header chain the runtime needs, following the order ACT4
 * itself uses in tests/env/riscv_arch_test.h: the udb-generated
 * rvtest_config.h comes before rvmodel_macros.h, and capabilities.h last
 * because it normalizes the <EXT>_SUPPORTED flags rvtest_config.h declares.
 */

#ifndef C_COMMON_ACT4_CONFIG_H
#define C_COMMON_ACT4_CONFIG_H

/* Generated by udb-gen cfg-c-header for the active config; declares the
 * <EXT>_SUPPORTED presence flags. */
#include "rvtest_config.h"

#ifdef __ASSEMBLER__
/* rvmodel_macros.h is assembly-only: it uses `#` comments and expands to
 * assembler directives. C code does not reference any RVMODEL_* macro. */
#include "rvmodel_macros.h"
#else
/* platform_config.h is C-only: it defines the platform address map. */
#include "platform_config.h"
#endif

/* Normalizes <EXT>_SUPPORTED into <EXT>_AVAILABLE 1/0 flags, so it must be
 * force-included after rvtest_config.h. */
#include "capabilities.h"

#endif /* C_COMMON_ACT4_CONFIG_H */
